import ApplicationServices
import Foundation

func attr(_ el: AXUIElement, _ name: String) -> AnyObject? {
    var v: AnyObject?
    let e = AXUIElementCopyAttributeValue(el, name as CFString, &v)
    return e == .success ? v : nil
}

var seen = Set<String>()
func walk(_ el: AXUIElement, depth: Int = 0) {
    let role = attr(el, kAXRoleAttribute as String) as? String ?? ""
    let subrole = attr(el, kAXSubroleAttribute as String) as? String ?? ""
    let title = attr(el, kAXTitleAttribute as String) as? String ?? ""
    let key = "\(role)|\(subrole)|\(title)"
    if !seen.contains(key), (!role.isEmpty || !title.isEmpty) {
        seen.insert(key)
        print(String(repeating: " ", count: min(depth, 4)), role, subrole, "|", title)
    }
    if depth > 8 { return }
    if let children = attr(el, kAXChildrenAttribute as String) as? [AXUIElement] {
        for c in children { walk(c, depth: depth + 1) }
    }
}

let app = AXUIElementCreateApplication(35695)
if let windows = attr(app, kAXWindowsAttribute as String) as? [AXUIElement], let w = windows.first {
    walk(w)
}
